    ('ova-shogakukan-10','[OVA] Shogakukan Illustrated Encyclopedia #10 - Crime Prevention Guide','ova',1,NULL,'2008-06-01',11,NULL,'Not for sale.','https://cdn.myanimelist.net/images/anime/7/75199l.jpg',NULL),
